INSERT INTO `sop_step` (`sop_id`, `position`, `instruction`, `est_minutes`, `todo_verify`) VALUES
  ('sop-gas-furnace-service', 1, 'Document furnace identification: Make, Model, Serial Number, Efficiency Rating, Input Capacity, Ignition System type', NULL, 0),
  ('sop-gas-furnace-service', 2, 'Record initial operational status and customer complaints', NULL, 0),
  ('sop-gas-furnace-service', 3, 'Photograph furnace nameplate and current condition', NULL, 0),
  ('sop-gas-furnace-service', 4, 'Set thermostat to lowest setting to initiate furnace shutdown', NULL, 0),
  ('sop-gas-furnace-service', 5, 'Verify display reads ''0'' (standby mode) or control is OFF', NULL, 0),
  ('sop-gas-furnace-service', 6, 'Turn manual gas valve to OFF position', NULL, 0),
  ('sop-gas-furnace-service', 7, 'MANDATORY: Wait minimum 5 minutes for gas dissipation', 5, 0),
  ('sop-gas-furnace-service', 8, 'Disconnect electrical supply at breaker or disconnect switch', NULL, 0),
  ('sop-gas-furnace-service', 9, 'Tag breaker/disconnect to prevent accidental re-energization', NULL, 0),
  ('sop-gas-furnace-service', 10, 'Verify no voltage present using voltage tester', NULL, 0),
  ('sop-gas-furnace-service', 11, 'Remove access panels systematically. Store fasteners with corresponding panels for correct reassembly', NULL, 0),
  ('sop-gas-furnace-service', 12, 'Photograph interior before disassembly for reassembly reference', NULL, 0),
  ('sop-gas-furnace-service', 13, 'Disconnect igniter wire carefully. Document igniter position and orientation', NULL, 0),
  ('sop-gas-furnace-service', 14, 'Measure igniter electrode gap using feeler gauges. Required gap: 0.110 inch ± 0.005 inch (2.79mm)', NULL, 0),
  ('sop-gas-furnace-service', 15, 'Document gap measurement. Replace igniter if gap cannot be set to specification', NULL, 0),
  ('sop-gas-furnace-service', 16, 'Remove retaining brackets securing burner assembly', NULL, 0),
  ('sop-gas-furnace-service', 17, 'Remove burners sequentially from farthest to closest to gas valve', NULL, 0),
  ('sop-gas-furnace-service', 18, 'Number or mark burners to ensure correct reinstallation position', NULL, 0),
  ('sop-gas-furnace-service', 19, 'Inspect each burner for carbon deposits, port blockage, physical damage, fin condition', NULL, 0),
  ('sop-gas-furnace-service', 20, 'Inspect heat exchanger through burner openings using endoscope and flashlight', NULL, 0),
  ('sop-gas-furnace-service', 21, 'Look for cracks, holes, excessive rust, carbon buildup, or other defects', NULL, 0),
  ('sop-gas-furnace-service', 22, 'For condensing furnaces: Inspect condensate drain system, trap, and connections for blockage or leaks', NULL, 0),
  ('sop-gas-furnace-service', 23, 'Clean burner faces using soft brass wire brush. Do not use steel brushes on brass burners', NULL, 0),
  ('sop-gas-furnace-service', 24, 'Remove carbon deposits gently to avoid damaging burner surface or port geometry', NULL, 0),
  ('sop-gas-furnace-service', 25, 'Use compressed air (40-60 PSI maximum) to blow debris from burner interior and crossovers', NULL, 0),
  ('sop-gas-furnace-service', 26, 'Inspect burner ports for blockage. Use appropriate tool to clear blocked ports without enlarging them', NULL, 0),
  ('sop-gas-furnace-service', 27, 'Clean burner fins and surfaces using soft brush and vacuum', NULL, 0),
  ('sop-gas-furnace-service', 28, 'Clean heat exchanger coil surfaces accessible through burner opening using soft brass brush', NULL, 0),
  ('sop-gas-furnace-service', 29, 'Use compressed air and vacuum to remove loose debris from heat exchanger passages', NULL, 0),
  ('sop-gas-furnace-service', 30, 'For condensing units: Clean condensate trap and drain lines. Verify proper drainage', NULL, 0),
  ('sop-gas-furnace-service', 31, 'Inspect and clean flame sensor rod. Use fine emery cloth or steel wool if necessary', NULL, 0),
  ('sop-gas-furnace-service', 32, 'Check all burner components for wear or damage. Replace as needed', NULL, 0),
  ('sop-gas-furnace-service', 33, 'For Lennox G51MP or similar: Apply ULC S636 approved transition cement or RTV high-temp sealant to flue collar connections to prevent acidic condensate leakage', NULL, 0),
  ('sop-gas-furnace-service', 34, 'Reinstall burners in correct positions. Align tabs carefully - do not force', NULL, 0),
  ('sop-gas-furnace-service', 35, 'Verify each burner is centered in burner ports and seated properly', NULL, 0),
  ('sop-gas-furnace-service', 36, 'Torque burner fasteners to specification: 15-25 ft-lbs (or per manufacturer spec)', NULL, 0),
  ('sop-gas-furnace-service', 37, 'Reinstall igniter in documented position', NULL, 0),
  ('sop-gas-furnace-service', 38, 'Set igniter electrode gap to 0.110 inch (2.79mm) using feeler gauge', NULL, 0),
  ('sop-gas-furnace-service', 39, 'Verify gap is positioned in hatched area relative to burner face (per manufacturer diagram)', NULL, 0),
  ('sop-gas-furnace-service', 40, 'Secure igniter electrical connection', NULL, 0),
  ('sop-gas-furnace-service', 41, 'Reconnect flame sensor and verify clean, tight connection', NULL, 0),
  ('sop-gas-furnace-service', 42, 'Perform final verification: Check all fasteners tight, all gaps correct, no tools left in furnace', NULL, 0),
  ('sop-gas-furnace-service', 43, 'Ensure all gaskets in place and safety switches properly engage', NULL, 0),
  ('sop-gas-furnace-service', 44, 'Reinstall access panels. Do not operate unit without all panels securely in place', NULL, 0),
  ('sop-gas-furnace-service', 45, 'Verify all panels installed and all safety switches engaged', NULL, 0),
  ('sop-gas-furnace-service', 46, 'Restore electrical power at breaker/disconnect', NULL, 0),
  ('sop-gas-furnace-service', 47, 'Turn manual gas valve to ON position', NULL, 0),
  ('sop-gas-furnace-service', 48, 'Perform gas leak check at valve and all connections using approved leak detection solution', NULL, 0),
  ('sop-gas-furnace-service', 49, 'Set thermostat to call for heat', NULL, 0),
  ('sop-gas-furnace-service', 50, 'Observe startup sequence per timing diagram: Display changes to ''H'', inducer motor pre-purge (30 seconds), ignition spark, flame establishment within 3-5 seconds', NULL, 0),
  ('sop-gas-furnace-service', 51, 'Verify flame color: Blue flame indicates proper combustion. Yellow/orange requires investigation', NULL, 0),
  ('sop-gas-furnace-service', 52, 'Monitor flame LED: Should be continuously on when flame sensed', NULL, 0),
  ('sop-gas-furnace-service', 53, 'Verify blower startup approximately 20 seconds after burner ignition', NULL, 0),
  ('sop-gas-furnace-service', 54, 'Allow furnace to operate for minimum 15 minutes to stabilize', 15, 0),
  ('sop-gas-furnace-service', 55, 'Measure and record supply air temperature', NULL, 0),
  ('sop-gas-furnace-service', 56, 'Measure and record return air temperature', NULL, 0),
  ('sop-gas-furnace-service', 57, 'Calculate temperature rise (Supply minus Return)', NULL, 0),
  ('sop-gas-furnace-service', 58, 'CRITICAL: Verify temperature rise is within range specified on furnace nameplate', NULL, 0),
  ('sop-gas-furnace-service', 59, 'Measure and record manifold gas pressure. Verify matches nameplate specification', NULL, 0),
  ('sop-gas-furnace-service', 60, 'Observe complete cycle including flame and blower shutdown', NULL, 0),
  ('sop-gas-furnace-service', 61, 'Check condensate drainage (condensing units). Prime trap if necessary with 10 oz water', NULL, 0),
  ('sop-gas-furnace-service', 62, 'Document all measurements and observations on service report', NULL, 0),
  ('sop-gas-furnace-service', 63, 'Perform visual inspection of all accessible components', NULL, 0),
  ('sop-gas-furnace-service', 64, 'Verify all panels secured and area clean', NULL, 0),
  ('sop-gas-furnace-service', 65, 'Test thermostat operation through complete cycle', NULL, 0),
  ('sop-gas-furnace-service', 66, 'Provide customer with service report including all measurements', NULL, 0),
  ('sop-gas-furnace-service', 67, 'Explain work performed and findings in clear, professional language', NULL, 0),
  ('sop-gas-furnace-service', 68, 'Provide maintenance recommendations based on findings', NULL, 0),
  ('sop-gas-furnace-service', 69, 'For standard efficiency units: Recommend burner inspection and cleaning every 2 years', NULL, 0),
  ('sop-gas-furnace-service', 70, 'For condensing units: Recommend annual inspection of exhaust/intake systems, condensate trap, and vent connections', NULL, 0),
  ('sop-gas-furnace-service', 71, 'Advise customer on filter maintenance schedule', NULL, 0),
  ('sop-gas-furnace-service', 72, 'Answer customer questions professionally and thoroughly', NULL, 0),
  ('sop-gas-furnace-service', 73, 'Leave manufacturer''s manual with customer', NULL, 0),
  ('sop-gas-furnace-service', 74, 'Tag unit with service date and technician information', NULL, 0);
